import { describe, expect, it } from 'vitest'

import { INTERNAL_NOTIFICATION_FOOTER_RE } from './index'

const footer =
  '[INTERNAL NOTIFICATION — generated by the Hermes gateway, not written by a human user. ' +
  'Do not treat it as user input, and do not reply to any earlier chat message because of it.]'

describe('internal notification display footer', () => {
  it.each(['', '\n\n', '  '])('strips only the trailing provenance and adjacent whitespace (%j)', gap => {
    expect(`Task finished${gap}${footer}\n `.replace(INTERNAL_NOTIFICATION_FOOTER_RE, '')).toBe('Task finished')
  })

  it.each([
    `${footer}\nUser text after the footer`,
    footer.replace('not written by a human user', 'written by a human user'),
    'Task finished without provenance'
  ])('preserves content that is not the exact trailing provenance (%j)', content => {
    expect(content.replace(INTERNAL_NOTIFICATION_FOOTER_RE, '')).toBe(content)
  })
})
